import * as THREE from 'three';
import { describe, expect, it } from 'vitest';
import {
  boardReclineFor, FLAT_CAMERA, FOLD_CAMERA, fovForAspect, OPEN_CAMERA, PIN_BOARD,
} from '../src/game/CoinPusher.js';
import { nodeBoxes, overallBounds, readGlb } from './glb.js';
import { GAME } from '../src/game/config.js';

// The slot machine is generated by tools/build_slot.py. Unlike the launcher it does go through
// fitProp(), which scales by the model's own X extent - so the model authoring itself exactly
// GAME.slotWidth wide is what keeps that scale at 1.0 and every number here in world units.
//
// Coordinates are local to the slot group, which sits at (0, GAME.slotY, GAME.slotZ). Local y is
// height above slotY; local z + slotZ is world z; the player is at -Z.
const MODEL = 'public/models/slot.glb';

// Where the crown lands in every camera pose: lying flat off a foldable (669 x 768 under the HUD),
// and on a foldable open and stood up, on the full-height canvas (669 x 812) with the sill on the
// fold 475.5 pt down (html[data-fold]). Model-local bounds are at scale 1; the machine is enlarged
// by slotScale.
const crownInFrame = (bounds) => {
  const crown = new THREE.Vector3(
    (bounds.max[0] * GAME.slotScale),
    GAME.slotY + bounds.max[1] * GAME.slotScale,
    GAME.slotZ + bounds.min[2] * GAME.slotScale,
  );
  // As the game draws it: the slot reclines with the board about its sill (boardReclineFor), and
  // stood up the frame slides to put that sill on the fold.
  const pivot = new THREE.Vector3(0, PIN_BOARD.bottom - 0.1, GAME.dropZoneZ - 0.1);
  const flat = 669 / 768;
  const stood = 669 / 812;
  return [
    [FLAT_CAMERA, fovForAspect(flat), flat, 0, 0],
    [OPEN_CAMERA, OPEN_CAMERA.fov, stood, 1, 1 - (2 * 475.5) / 812],
    [FOLD_CAMERA, FOLD_CAMERA.fov, stood, 1, 1 - (2 * 475.5) / 812],
  ].every(([pose, fov, aspect, fold, foldNdc]) => {
    const camera = new THREE.PerspectiveCamera(fov, aspect, 0.1, 100);
    camera.position.set(...pose.position);
    camera.lookAt(...pose.target);
    camera.updateMatrixWorld();
    const recline = boardReclineFor(camera.getWorldDirection(new THREE.Vector3()));
    const shift = (foldNdc - pivot.clone().project(camera).y) * fold;
    const ndc = crown.clone().sub(pivot).applyAxisAngle(new THREE.Vector3(1, 0, 0), recline).add(pivot).project(camera);
    return ndc.y + shift < 1 && Math.abs(ndc.x) < 1;
  });
};

const box = (x, y, z) => ({ x, y, z });
const mirror = (name, spec) => ({
  [`${name}_L`]: box([-spec.x[1], -spec.x[0]], spec.y, spec.z),
  [`${name}_R`]: spec,
});

const WINDOW = [-0.70, 0.70];
const WINDOW_Y = [0.40, 0.85];
const FACE_Z = [-0.28, -0.12];
const THIRD = (WINDOW[1] - WINDOW[0]) / 6;

const PARTS = {
  slot_plinth: box([-1.12, 1.12], [0.00, 0.09], [-0.34, 0.32]),
  slot_plinth_glow: box([-0.86, 0.86], [0.03, 0.05], [-0.35, -0.34]),
  slot_core: box([-1.00, 1.00], [0.09, 0.94], [-0.12, 0.30]),
  slot_face_lower: box([-1.00, 1.00], [0.09, 0.40], FACE_Z),
  slot_face_upper: box([-1.00, 1.00], [0.85, 0.94], FACE_Z),
  ...mirror('slot_face_side', box([0.72, 1.00], [0.40, 0.85], FACE_Z)),
  slot_reel_glass: box(WINDOW, WINDOW_Y, [-0.13, -0.12]),
  ...mirror('slot_mullion', box([THIRD - 0.012, THIRD + 0.012], WINDOW_Y, [-0.17, -0.155])),
  ...mirror('slot_pylon', box([1.00, 1.12], [0.09, 1.00], [-0.30, 0.30])),
  ...mirror('slot_pylon_glow', box([1.03, 1.09], [0.16, 0.92], [-0.32, -0.30])),
  slot_crown: box([-0.94, 0.94], [0.94, 1.18], [-0.24, 0.28]),
  slot_ring_teal: box([-0.86, 0.86], [0.94, 1.18], [-0.27, -0.23]),
  slot_ring_gold: box([-0.54, 0.54], [0.98, 1.14], [-0.27, -0.23]),
};

describe('slot machine model', () => {
  const gltf = readGlb(MODEL);
  const boxes = nodeBoxes(gltf);
  const bounds = overallBounds(boxes);
  const byName = Object.fromEntries(boxes.map((entry) => [entry.name, entry]));

  it('ships no textures and borrows the machine\'s own materials', () => {
    expect(gltf.images ?? []).toHaveLength(0);
    for (const material of gltf.materials) {
      // The matte pair, not the polished one the cabinet is built from. This is the only model
      // in the machine that faces the camera square, with a 5.2-intensity point light 1.5 units
      // in front of it - polished here is a mirror of the hall with a flare pinned to the middle.
      expect([
        'shell_matte', 'trim_gold_matte', 'trim_teal_matte', 'reel_glass',
      ]).toContain(material.name);
    }
  });

  // The readout is a plain unlit canvas plane - it renders at whatever brightness the canvas is
  // and cannot be turned up. So it only reads as the machine's focal point while nothing around
  // it out-shines it, and on a body this small every strip is within bloom's spill radius of the
  // window. The rule that keeps it legible: no emitter on this model goes over 1.0.
  //
  // The exporter is what measures that. It writes emissive into emissiveFactor while the colour
  // times the strength still fits in [0, 1], and only reaches for KHR_materials_emissive_strength
  // when it does not - so the extension appearing in this file means something here is a lamp
  // again. neon_gold_soft's 1.4 on gold lands at 1.22 and trips it, which is how the crown ring
  // and the two rails ended up as trim_gold.
  it('carries its emissive without needing the strength extension', () => {
    expect(gltf.extensionsUsed ?? []).not.toContain('KHR_materials_emissive_strength');
    const lit = gltf.materials.filter((material) => material.emissiveFactor?.some((c) => c > 0));
    expect(lit.map((material) => material.name)).toContain('trim_teal_matte');
  });

  it('holds exactly the parts the design lists', () => {
    expect(boxes.map((entry) => entry.name).sort()).toEqual(Object.keys(PARTS).sort());
  });

  describe('each part stands where the design says', () => {
    for (const { name, min, max } of boxes) {
      it(name, () => {
        const spec = PARTS[name];
        for (const [axis, key] of [[0, 'x'], [1, 'y'], [2, 'z']]) {
          expect(min[axis], `${name} ${key} min`).toBeGreaterThanOrEqual(spec[key][0] - 0.01);
          expect(max[axis], `${name} ${key} max`).toBeLessThanOrEqual(spec[key][1] + 0.01);
        }
      });
    }
  });

  // fitProp() scales by X. Authoring the model at exactly slotWidth keeps that scale at 1.0, which
  // is the only reason the numbers above can be read as world units - and the only reason the
  // height check below means anything.
  it('is born the width fitProp would scale it to', () => {
    expect(bounds.max[0] - bounds.min[0]).toBeCloseTo(GAME.slotWidth, 3);
    expect(bounds.min[1]).toBeCloseTo(0, 3);
  });

  // buildBonusStage() finds the pane by material name, measures it and lays the canvas readout
  // 0.01 in front. Three symbols get an even third of that width each, so the mullions have to
  // land on the thirds or the drums read as misaligned with their own dividers.
  it('divides the reel pane into the three the readout draws', () => {
    const pane = gltf.materials.findIndex((material) => material.name === GAME.slotReelMaterial);
    expect(pane, `no ${GAME.slotReelMaterial} material`).toBeGreaterThanOrEqual(0);
    const wearing = gltf.nodes
      .filter((node) => gltf.meshes[node.mesh].primitives
        .some((primitive) => primitive.material === pane))
      .map((node) => node.name);
    expect(wearing).toEqual(['slot_reel_glass']);

    const glass = byName.slot_reel_glass;
    const width = glass.max[0] - glass.min[0];
    for (const [name, sign] of [['slot_mullion_L', -1], ['slot_mullion_R', 1]]) {
      const centre = (byName[name].min[0] + byName[name].max[0]) / 2;
      expect(centre).toBeCloseTo(sign * width / 6, 3);
    }
  });

  // The readout is an opaque plane at the pane's front face less 0.01. Anything reaching into the
  // window's footprint in front of that plane is drawn over the symbols. The face plates butt
  // straight onto the opening's edges, and those edges come back out of the GLB as float32 - so
  // this asks for a real bite out of the window, not a shared edge.
  it('leaves the readout unobstructed', () => {
    const BITE = 0.01;
    const glass = byName.slot_reel_glass;
    const readoutZ = glass.min[2] - 0.01;
    for (const { name, min, max } of boxes) {
      if (name === 'slot_reel_glass' || name.startsWith('slot_mullion')) continue;
      const overlaps = min[2] < readoutZ
        && max[0] > glass.min[0] + BITE && min[0] < glass.max[0] - BITE
        && max[1] > glass.min[1] + BITE && min[1] < glass.max[1] - BITE;
      expect(overlaps, `${name} covers the readout`).toBe(false);
    }
  });
});

// The Tripo machine, fitted by tools/fit_tripo.py. It is one textured mesh, so the part-by-part
// checks above do not apply; what the loader needs from it is the same.
describe('Tripo slot machine model', () => {
  const gltf = readGlb('public/models/slot_tripo.glb');
  const boxes = nodeBoxes(gltf);
  const bounds = overallBounds(boxes);
  const glass = boxes.find((entry) => entry.name === 'slot_reel_glass');

  it('is born at slotWidth, standing on y = 0, inside the shot', () => {
    expect(bounds.max[0] - bounds.min[0]).toBeCloseTo(GAME.slotWidth, 3);
    expect(bounds.min[1]).toBeCloseTo(0, 3);
    expect(crownInFrame(bounds)).toBe(true);
  });

  it('carries exactly one reel pane, in the model\'s front half', () => {
    const pane = gltf.materials.findIndex((material) => material.name === GAME.slotReelMaterial);
    expect(pane).toBeGreaterThanOrEqual(0);
    expect(glass, 'no slot_reel_glass node').toBeDefined();
    for (const axis of [0, 1]) {
      expect(glass.min[axis]).toBeGreaterThan(bounds.min[axis]);
      expect(glass.max[axis]).toBeLessThan(bounds.max[axis]);
    }
    // Recessed behind the frame, but still in front of the body's centre: the player is at -Z.
    expect(glass.min[2]).toBeGreaterThan(bounds.min[2]);
    expect(glass.max[2]).toBeLessThan(0);
  });

  it('lights its mint pillars from an emissive map', () => {
    const body = gltf.materials.find((material) => material.name !== GAME.slotReelMaterial);
    expect(body.emissiveTexture).toBeDefined();
  });
});
